effect.shader:
void main(){
vec2 uv = acScreenNorm;
vec4 src = texture2DCv(inputImg.texture, uv);
float aspect = max(getTexSize(inputImg.size).x / max(getTexSize(inputImg.size).y, 1.0), 0.5);
vec2 c = vec2(spotX * 0.01, spotY * 0.01);
float d = length((uv - c) * vec2(1.0, aspect));
float rad = spotRadius * 0.01;
float soft = max(spotSoft, 0.03) * rad;
float spot = 1.0 - smoothstep(rad - soft, rad, d);
if (stageFlicker) {
spot *= 0.96 + 0.04 * sin(acTime * 47.0) * sin(acTime * 13.7);
}
vec3 inside = src.rgb * (1.0 + spotBoost * spot);
vec3 outside = mix(src.rgb, dimTint.rgb * dot(src.rgb, vec3(0.333)) * 2.2, dimTintAmt);
outside *= (1.0 - outerDim * (1.0 - spot));
vec3 col = mix(outside, inside, spot);
gl_FragColor = vec4(clamp(col, 0.0, 2.0) * src.a, src.a);
}
